added = {}
for lang, items in A.items():
    f = os.path.join(ROOT, lang + '.json')
    data = json.load(open(f, encoding='utf-8'))
    names = {i['name'] for i in data}
    n = 0
    for name, desc, cat, snippet in items:
        if name in names:
            continue
        data.append({'name': name, 'desc': desc, 'cat': cat, 'snippet': snippet})
        names.add(name); n += 1
    with open(f, 'w', encoding='utf-8') as out:
        json.dump(data, out, indent=1, ensure_ascii=False)
        out.write('\n')
    added[lang] = (n, len(data))
for k, (n, t) in added.items():
    print(f'{k}: +{n} -> {t}')
